# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(gather(shape(render(raw))))

